//! Render Composer's static PHP loader maps, using its array formatting.

use super::Maps;
use crate::php;
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

pub(super) fn render(maps: &Maps, vendor: &Path, root: &Path, suffix: &str) -> String {
    let composer = vendor.join("composer");
    let path = |file: &Path| php::static_path(file, &composer, vendor, root);
    let mut code = format!(
        "<?php\n\n// autoload_static.php @generated by Composer\n\n\
        namespace Composer\\Autoload;\n\nclass ComposerStaticInit{suffix}\n{{\n"
    );
    let paths = |files: &[PathBuf]| {
        array(
            files
                .iter()
                .enumerate()
                .map(|(key, file)| (key.to_string(), path(file))),
        )
    };
    let psr4 = maps
        .psr4
        .iter()
        .rev()
        .filter(|(prefix, _)| !prefix.is_empty());
    let definitions = [
        (
            "files",
            array(
                maps.files
                    .iter()
                    .map(|(key, file)| (php::quote(key), path(file))),
            ),
        ),
        (
            "prefixLengthsPsr4",
            groups(psr4.clone().map(|(key, _)| (key, key.len().to_string()))),
        ),
        (
            "prefixDirsPsr4",
            array(psr4.filter_map(|(key, files)| Some((php::quote(key), paths(files)?)))),
        ),
        (
            "fallbackDirsPsr4",
            maps.psr4.get("").and_then(|files| paths(files)),
        ),
        (
            "prefixesPsr0",
            groups(maps.psr0.iter().rev().filter_map(|(key, files)| {
                (!key.is_empty())
                    .then(|| paths(files))
                    .flatten()
                    .map(|value| (key, value))
            })),
        ),
        (
            "fallbackDirsPsr0",
            maps.psr0.get("").and_then(|files| paths(files)),
        ),
        (
            "classMap",
            array(
                maps.classes
                    .iter()
                    .map(|(key, file)| (php::quote_bytes(key), path(file))),
            ),
        ),
    ];
    let mut initializer = String::new();
    for (property, value) in definitions {
        if let Some(value) = value {
            code.push_str(&format!(
                "    public static ${property} = {};\n\n",
                indent(&value)
            ));
            if property != "files" {
                initializer.push_str(&format!(
                    "            $loader->{property} = ComposerStaticInit{suffix}::${property};\n"
                ));
            }
        }
    }
    code.push_str(concat!(
        "    public static function getInitializer(ClassLoader $loader)\n",
        "    {\n",
        "        return \\Closure::bind(function () use ($loader) {\n",
    ));
    code.push_str(&initializer);
    code.push_str("\n        }, null, ClassLoader::class);\n    }\n}\n");
    code
}

fn groups<'a>(entries: impl Iterator<Item = (&'a String, String)>) -> Option<String> {
    let mut groups = BTreeMap::<char, Vec<(String, String)>>::new();
    for (key, value) in entries {
        if let Some(first) = key.chars().next() {
            groups
                .entry(first)
                .or_default()
                .push((php::quote(key), value));
        }
    }
    array(
        groups
            .into_iter()
            .rev()
            .filter_map(|(key, entries)| Some((php::quote(&key.to_string()), array(entries)?))),
    )
}

fn array(entries: impl IntoIterator<Item = (String, String)>) -> Option<String> {
    let mut entries = entries.into_iter().peekable();
    entries.peek()?;
    let mut output = String::from("array (\n");
    for (key, value) in entries {
        let separator = if value.starts_with("array (") {
            "\n    "
        } else {
            " "
        };
        output.push_str(&format!("    {key} =>{separator}{},\n", indent(&value)));
    }
    output.push(')');
    Some(output)
}

fn indent(contents: &str) -> String {
    contents.replace('\n', "\n    ")
}
